  "file": "./02_Knowledge/technologies/services/forgejo/backup-verification.md",
  "folder": "02_Knowledge",
  "types": {
    "source": [
      {
        "severity": "S2",
        "issue": "The only citation is an internal homelab wiki that is not authoritative for the claim it supports and cannot be verified from the review environment.",
        "evidence": "sources[0].url = \"https://wiki.homelab.local/forgejo/backup-design\" — fetching it returns a transport error, so it cannot be confirmed live or confirmed to say what is claimed. The claim it backs (LFS objects included in the dump by default) is Forgejo product behavior, whose authoritative source is the Forgejo CLI docs (https://forgejo.org/docs/latest/admin/command-line/), which document LFS as included by default via the `--skip-lfs-data` opt-out.",
        "fix_hint": "Keep the wiki citation for the homelab-specific migration detail, but add the Forgejo CLI reference (https://forgejo.org/docs/latest/admin/command-line/) as the authoritative source for the default-inclusion behavior."
      }
    ],
    "accuracy": [],
    "scope": [],
    "structure": [
      {
        "severity": "S4",
        "issue": "Tags are not lowercase kebab-case.",
        "evidence": "Line 6: `tags: [Forgejo, Backup_Verification]`. Root AGENTS.md requires tags to match `^[a-z0-9]+(-[a-z0-9]+)*$`; the section example uses `tags: [kubernetes, networking, ingress]`.",
        "fix_hint": "Use `tags: [forgejo, backup-verification]` (do not use TitleCase/underscores)."
      },
      {
        "severity": "S4",
        "issue": "Required frontmatter field `last_audit_date` is missing.",
        "evidence": "02_Knowledge/AGENTS.md frontmatter spec and ./Templates/knowledge/note.md both list `last_audit_date: YYYY-MM-DD` as required; the note's frontmatter (lines 1-11) has title/status/author/date/tags/sources/related_docs but no last_audit_date.",
        "fix_hint": "Add `last_audit_date: 2026-10-21` (today's date) after the `sources` block."
      }
    ],
    "overlap": []
  },
  "totals": { "S1": 0, "S2": 1, "S3": 0, "S4": 2 },
